SET search_path TO lms, extensions;

-- Existing child rows remain lessons directly under their tracks. A module
-- heading is optional, so current sessions, progress, and PDFs keep their IDs.
ALTER TABLE lms.modules
  ADD COLUMN IF NOT EXISTS module_group text;

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conrelid = 'lms.modules'::regclass
      AND conname = 'modules_module_group_child_only'
  ) THEN
    ALTER TABLE lms.modules
      ADD CONSTRAINT modules_module_group_child_only
      CHECK (module_group IS NULL OR (
        parent_id IS NOT NULL
        AND length(btrim(module_group)) BETWEEN 1 AND 100
      ));
  END IF;
END;
$$;

COMMENT ON COLUMN lms.modules.module_group IS
  'Optional module heading for a lesson within a track; null means a direct track lesson.';
